-- Production-ready relational schema for migration from the development JSON store.
CREATE TABLE roles (id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, login TEXT UNIQUE, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role_id INTEGER NOT NULL REFERENCES roles(id), blocked BOOLEAN DEFAULT FALSE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, deleted_at DATETIME);
CREATE TABLE cities (id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, status TEXT NOT NULL DEFAULT 'Published');
CREATE TABLE categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Published');
CREATE TABLE media (id INTEGER PRIMARY KEY, filename TEXT NOT NULL, mime_type TEXT, url TEXT NOT NULL, alt TEXT, created_by INTEGER REFERENCES users(id), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, deleted_at DATETIME);
CREATE TABLE companies (id INTEGER PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, category_id INTEGER REFERENCES categories(id), city_id INTEGER REFERENCES cities(id), type TEXT NOT NULL, status TEXT NOT NULL, description TEXT, logo_id INTEGER REFERENCES media(id), cover_id INTEGER REFERENCES media(id), author_id INTEGER REFERENCES users(id), deleted_at DATETIME);
CREATE TABLE products (id INTEGER PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, company_id INTEGER REFERENCES companies(id), category_id INTEGER REFERENCES categories(id), city_id INTEGER REFERENCES cities(id), price DECIMAL CHECK(price >= 0), type TEXT NOT NULL, status TEXT NOT NULL, description TEXT, deleted_at DATETIME);
CREATE TABLE services (id INTEGER PRIMARY KEY, name TEXT NOT NULL, company_id INTEGER REFERENCES companies(id), category_id INTEGER REFERENCES categories(id), city_id INTEGER REFERENCES cities(id), price DECIMAL CHECK(price >= 0), price_negotiable BOOLEAN DEFAULT FALSE, status TEXT NOT NULL, deleted_at DATETIME);
CREATE TABLE universities (id INTEGER PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, city_id INTEGER REFERENCES cities(id), description TEXT, deleted_at DATETIME);
CREATE TABLE students (id INTEGER PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, university_id INTEGER REFERENCES universities(id), city_id INTEGER REFERENCES cities(id), status TEXT, deleted_at DATETIME);
CREATE TABLE articles (id INTEGER PRIMARY KEY, title TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, category_id INTEGER REFERENCES categories(id), author_id INTEGER REFERENCES users(id), status TEXT NOT NULL, content TEXT NOT NULL, published_at DATETIME, deleted_at DATETIME);
CREATE TABLE pages (id INTEGER PRIMARY KEY, title TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, status TEXT NOT NULL, content TEXT NOT NULL, seo_title TEXT, seo_description TEXT, og_image_id INTEGER REFERENCES media(id), deleted_at DATETIME);
CREATE TABLE reviews (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, text TEXT NOT NULL, rating INTEGER CHECK(rating BETWEEN 1 AND 5), status TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE subscribers (id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, status TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT, entity_id INTEGER, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
